type Lang='fa'|'en';
const LocaleContext=createContext<{lang:Lang,t:(fa:string,en:string)=>string,n:(x:number|string)=>string,date:(s:string,opts?:Intl.DateTimeFormatOptions)=>string}>({lang:'fa',t:f=>f,n:String,date:s=>s});
const useL=()=>useContext(LocaleContext);
const uid=()=>crypto.randomUUID();
const labels={dashboard:['پیشخوان','Overview'],students:['زبان‌آموزان','Students'],schedule:['برنامه کلاس‌ها','Schedule'],finance:['شهریه و تسویه','Finance'],messages:['گفتگوها','Messages'],settings:['تنظیمات','Settings'],studio:['پرتفولیو و بلاگ','Portfolio & blog'],admin:['صندوق مدیر','Admin inbox']} as const;
const skillNames={listening:['شنیداری','Listening'],speaking:['گفتاری','Speaking'],reading:['خواندن','Reading'],writing:['نوشتاری','Writing']} as const;
const skillIcons={listening:Headphones,speaking:Mic,reading:BookOpen,writing:PenLine};
function Avatar({student,name,large=false,photo}:{student?:Student,name?:string,large?:boolean,photo?:string}){const label=student?.name||name||'م';return <span className={`avatar tone-${student?.tone||0} ${large?'large':''}`}>{photo?<img src={photo} alt={label}/>:label.split(' ').slice(0,2).map(s=>s[0]).join(' ')}</span>}
function Choice({value,onChange,options,id,label}:{value:string,onChange:(v:string)=>void,options:readonly (readonly [string,string])[],id?:string,label?:string}){const {lang}=useL();return <Select value={value} onValueChange={onChange} dir={lang==='fa'?'rtl':'ltr'}><SelectTrigger className="select-input" id={id} aria-label={label}><SelectValue/></SelectTrigger><SelectContent>{options.map(([v,l])=><SelectItem key={v} value={v}>{l}</SelectItem>)}</SelectContent></Select>}
function Empty({text,action}:{text:string,action?:React.ReactNode}){return <EmptyPrimitive className="empty-state" style={{gap:12}}><EmptyHeader><BookOpen/><EmptyDescription>{text}</EmptyDescription></EmptyHeader>{action&&<EmptyContent>{action}</EmptyContent>}</EmptyPrimitive>}
function SectionHead({title,sub,action}:{title:string,sub?:string,action?:React.ReactNode}){return <div className="panel-head"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>}
function Status({session}:{session:Session}){const {t}=useL();return <span className={'badge '+(session.status==='cancelled'?'gray':session.status==='scheduled'?'purple':'')}>{session.status==='held'?t('برگزار شده','Completed'):session.status==='cancelled'?t('لغو شده','Cancelled'):t('برنامه‌ریزی شده','Scheduled')}</span>}
function SidebarNav({route,w,lang,isAdmin}:{route:string,w:Workspace,lang:Lang,isAdmin:boolean}){const {t,n}=useL();const {setOpenMobile}=useSidebar();const items=[['dashboard',LayoutDashboard,'/dashboard'],['students',Users,'/students'],['schedule',CalendarDays,'/schedule'],['finance',Wallet,'/finance'],['messages',MessageSquare,'/messages'],['studio',BookOpen,'/studio'],['admin',ShieldCheck,'/admin']] as const;return <Sidebar side={lang==='fa'?'right':'left'}>
 <Link className="brand" href="/" onClick={()=>setOpenMobile(false)}><span className="brand-mark"><BookOpen size={25} strokeWidth={1.7}/></span><div><div className="brand-name" dir="ltr">Mah<b>ELA</b><span style={{color:'var(--primary)'}}>.</span></div><p>{t('فضای رشد و یادگیری','A SPACE FOR LEARNING')}</p></div></Link>
 <SidebarContent><div className="nav-label">{t('فضای کار معلم','TEACHER WORKSPACE')}</div><SidebarGroup className="px-4 py-0"><SidebarGroupContent><SidebarMenu className="gap-2">{items.filter(([key])=>key!=='admin'||isAdmin).map(([key,Icon,url])=><SidebarMenuItem key={key}><SidebarMenuButton asChild isActive={route===key} className="nav-link"><Link href={url} onClick={()=>setOpenMobile(false)}><Icon/><span>{t(labels[key][0],labels[key][1])}</span>{key==='students'&&<span className="nav-count">{n(w.students.length)}</span>}</Link></SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu></SidebarGroupContent></SidebarGroup>
 <div className="nav-label" style={{marginTop:25}}>{t('حساب کاربری','PERSONAL')}</div><SidebarGroup className="px-4 py-0"><SidebarMenu><SidebarMenuItem><SidebarMenuButton asChild isActive={route==='settings'} className="nav-link"><Link href="/settings" onClick={()=>setOpenMobile(false)}><Settings/><span>{t('تنظیمات','Settings')}</span></Link></SidebarMenuButton></SidebarMenuItem></SidebarMenu></SidebarGroup>
 <div className="sidebar-note"><GraduationCap className="note-icon" size={25} strokeWidth={1.5}/><h3 style={{fontSize:'.86rem'}}>{t('هر قدم، یک پیشرفت','Every step is progress')}</h3><p>{t('مسیر یادگیری هر زبان‌آموز را با ارزیابی‌های منظم دنبال کنید.','Keep every student’s learning journey moving with regular assessments.')}</p><Link className="text-link" href="/students" onClick={()=>setOpenMobile(false)} style={{marginTop:13}}>{t('مشاهده زبان‌آموزان','View students')}<ChevronLeft/></Link></div></SidebarContent>
 <SidebarFooter className="p-0"><Link href="/settings" onClick={()=>setOpenMobile(false)} className="profile-small"><Avatar name={w.profile.name} photo={w.profile.photo}/><div style={{flex:1}}><strong>{w.profile.name}</strong><p>{w.profile.specialization||t('معلم','Teacher')}</p></div><Settings size={16}/></Link></SidebarFooter>
 </Sidebar>}
function Metric({label,value,unit,foot,Icon,emphasis=false}:{label:string,value:React.ReactNode,unit?:string,foot:string,Icon:React.ElementType,emphasis?:boolean}){return <div className={'metric '+(emphasis?'emphasis':'')}><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon/></span></div><div className="metric-number">{value}{unit&&<small>{unit}</small>}</div><div className="metric-bottom">{foot}</div></div>}
function SessionRow({s,w,onEdit}:{s:Session,w:Workspace,onEdit:(s:Session)=>void}){const {t,n}=useL();const student=w.students.find(x=>x.id===s.studentId);return <div className="session-row"><div className="session-time"><span>{n(s.time)}</span><small>{n(endTime(s))}</small></div><div className="session-line"/><Avatar student={student}/><div className="session-info"><strong>{student?.name}</strong><p>{s.type==='online'?<Video/>:<MapPin/>}{s.type==='online'?t('کلاس آنلاین','Online class'):t('کلاس حضوری','In person')}<span>·</span><span className="ltr">{student?.level}</span><span>·</span>{n(s.duration)} {t('دقیقه','min')}</p></div>{s.status==='scheduled'?<button className="btn compact" onClick={()=>onEdit(s)}>{t('جزئیات','Details')}<ChevronLeft size={14}/></button>:<button onClick={()=>onEdit(s)} aria-label={t('مدیریت جلسه','Manage session')}><Status session={s}/></button>}</div>}
function WeekStrip({selected,onSelect,sessions}:{selected:string,onSelect:(s:string)=>void,sessions:Session[]}){const {date,n}=useL();const start=weekStart(selected);return <div className="week-strip">{Array.from({length:7},(_,i)=>addDays(start,i)).map(d=><button key={d} className={`day-pill ${selected===d?'selected':''} ${sessions.some(s=>s.date===d&&s.status!=='cancelled')?'has-class':''}`} onClick={()=>onSelect(d)} aria-pressed={selected===d}><span>{date(d,{weekday:'short'})}</span><b>{date(d,{day:'numeric'})}</b><span className="day-dot"/></button>)}</div>}
function RosterTable({students,w}:{students:Student[],w:Workspace}){const {t,n,date}=useL();return <Table className="roster-table"><TableHeader><TableRow><TableHead>{t('زبان‌آموز','Student')}</TableHead><TableHead>{t('سطح','Level')}</TableHead><TableHead>{t('میانگین مهارت','Skill average')}</TableHead><TableHead className="student-list-hide">{t('جلسه بعد','Next class')}</TableHead><TableHead><span className="sr-only">{t('پرونده','Profile')}</span></TableHead></TableRow></TableHeader><TableBody>{students.map(s=>{const next=w.sessions.filter(x=>x.studentId===s.id&&x.status==='scheduled'&&x.date>=dateKey(new Date())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];return <TableRow key={s.id}><TableCell><Link href={'/students/'+s.id} className="student-cell"><Avatar student={s}/><span><strong>{s.name}</strong><small>{t('زبان انگلیسی','English')}</small></span></Link></TableCell><TableCell><span className={'badge '+(['C1','C2'].includes(s.level)?'purple':s.level==='A2'?'amber':'')}>{s.level}</span></TableCell><TableCell><div className="skill-value"><span>{n(average(s.skills))}<span className="muted"> / {n(9)}</span></span><div className="skill-track"><span style={{width:average(s.skills)/9*100+'%'}}/></div></div></TableCell><TableCell className="student-list-hide">{next?date(next.date,{month:'short',day:'numeric'})+' · '+n(next.time):'—'}</TableCell><TableCell><Link className="icon-button" href={'/students/'+s.id} aria-label={t('پرونده ','Profile of ')+s.name}><ChevronLeft/></Link></TableCell></TableRow>})}</TableBody></Table>}

export default function TeacherWorkspace(){
 const path=usePathname()||'/';const router=useRouter();const route=(path.split('/')[1]||'dashboard') as keyof typeof labels;const studentId=path.split('/')[2];
 const [isAdmin,setIsAdmin]=useState(false);const [w,setW]=useState<Workspace>(emptyWorkspace());const [version,setVersion]=useState(0);const [loaded,setLoaded]=useState(false);const [busy,setBusy]=useState(false);const [loadError,setLoadError]=useState('');const [lang,setLang]=useState<Lang>('fa');const [dark,setDark]=useState(false);const [today,setToday]=useState('2026-09-05');const [selectedDay,setSelectedDay]=useState('2026-09-05');const [search,setSearch]=useState('');const [level,setLevel]=useState('all');const [modal,setModal]=useState<{type:'student'|'session'|'assessment',student?:Student,session?:Session}|null>(null);const [resetOpen,setResetOpen]=useState(false);
 const t=(fa:string,en:string)=>lang==='fa'?fa:en;const n=(x:number|string)=>typeof x==='number'?new Intl.NumberFormat(lang==='fa'?'fa-IR':'en-US',{maximumFractionDigits:2}).format(x):lang==='fa'?x.replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[+d]):x;
 const calendar=w.profile.calendar==='auto'?(lang==='fa'?'persian':'gregory'):w.profile.calendar;
 const date=(s:string,opts:Intl.DateTimeFormatOptions={day:'numeric',month:'long'})=>{const d=s.includes('T')?new Date(s):dateFrom(s);return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat(lang==='fa'?'fa-IR':'en-GB',{calendar,...opts}).format(d)};
 async function load(){setLoadError('');try{const r=await fetch('/api/workspace',{cache:'no-store'}),j=await r.json() as {data:Workspace;version:number;isAdmin:boolean;error?:string};if(!r.ok)throw Error(j.error);setW(j.data);setIsAdmin(j.isAdmin);setVersion(j.version);setLoaded(true)}catch(e){setLoadError((e as Error).message)}}
 useEffect(()=>{const day=dateKey(new Date());setToday(day);setSelectedDay(day);setLang(localStorage.getItem('mahela-language')==='en'?'en':'fa');setDark(localStorage.getItem('mahela-theme')==='dark');load()},[]);
 useEffect(()=>{document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';localStorage.setItem('mahela-language',lang)},[lang]);
 useEffect(()=>{document.documentElement.classList.toggle('dark',dark);localStorage.setItem('mahela-theme',dark?'dark':'light')},[dark]);
 useEffect(()=>{setSearch('');setLevel('all');document.title=(studentId?w.students.find(s=>s.id===studentId)?.name||t('پرونده','Profile'):labels[route]?t(labels[route][0],labels[route][1]):'MahELA')+' | MahELA'},[path,lang,w.students]);
 async function save(next:Workspace,message?:string){if(busy||!loaded)return false;setBusy(true);try{validateWorkspace(next,w);const r=await fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:next,version})});const j=await r.json() as {data:Workspace;version:number;error?:string};if(!r.ok)throw Error(j.error);setW(j.data);setVersion(j.version);if(message)toast.success(message);return true}catch(e){toast.error((e as Error).message,{duration:6500});return false}finally{setBusy(false)}}
 const addStudent=()=>setModal({type:'student'});const addSession=(student?:Student)=>{if(!w.students.length){toast(t('ابتدا یک زبان‌آموز اضافه کنید.','Add a student first.'));addStudent();return}setModal({type:'session',student})};
 const editSession=(session:Session)=>setModal({type:'session',session,student:w.students.find(s=>s.id===session.studentId)});
 const student=w.students.find(s=>s.id===studentId);const visibleStudents=w.students.filter(s=>(s.name+' '+s.email).toLowerCase().includes(search.toLowerCase())&&(level==='all'||s.level===level));
 const unpaid=w.sessions.filter(s=>billable(s)&&!s.paid);const start=weekStart(today);const weekSessions=w.sessions.filter(s=>s.date>=start&&s.date<addDays(start,7)&&s.status!=='cancelled');const totalHours=weekSessions.reduce((v,s)=>v+s.duration,0)/60;
 const heading=student?student.name:(labels[route]?t(labels[route][0],labels[route][1]):t('صفحه پیدا نشد','Page not found'));
 return <LocaleContext.Provider value={{lang,t,n,date}}><SidebarProvider style={{'--sidebar-width':'244px'} as React.CSSProperties} dir={lang==='fa'?'rtl':'ltr'}><SidebarNav route={route} w={w} lang={lang} isAdmin={isAdmin}/><div className="workspace">{busy&&<div className="loading-bar" role="status" aria-label={t('در حال ذخیره','Saving')}/>}
 <header className="topbar"><div className="crumb"><SidebarTrigger className="mobile-menu" aria-label={t('باز کردن منو','Open menu')}/><span>{t('فضای کار معلم','Teacher workspace')}</span><ChevronLeft size={13}/><strong>{heading}</strong></div><div className="top-actions"><span className="top-date">{date(today,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span><button className="icon-button" onClick={()=>setDark(!dark)} aria-label={t(dark?'حالت روشن':'حالت تیره',dark?'Light mode':'Dark mode')}>{dark?<Sun/>:<Moon/>}</button><button className="icon-button" onClick={()=>setLang(lang==='fa'?'en':'fa')} aria-label={t('تغییر زبان به انگلیسی','Switch to Persian')} style={{fontSize:'.73rem',fontWeight:650}}>{lang==='fa'?'EN':'فا'}</button><Link href="/settings" aria-label={t('حساب کاربری','My account')}><Avatar name={w.profile.name} photo={w.profile.photo}/></Link></div></header>
 <main className="main-content">{loadError&&<div className="save-error" role="alert"><span>{loadError}</span><button className="btn compact" onClick={load}><RefreshCw size={15}/>{t('تلاش دوباره','Retry')}</button></div>}
 {!loaded&&!loadError?<div className="empty-state"><LoaderCircle className="animate-spin"/><p>{t('فضای کار شما آماده می‌شود…','Loading your workspace…')}</p></div>:loaded&&<>
 {route==='dashboard'&&<><div className="page-heading"><div><h1>{t('روز بخیر، '+w.profile.name.split(' ')[0]+'!','Hello, '+w.profile.name+'!')} <span style={{fontSize:'1.3rem'}}>☀</span></h1><p>{t('امروز، یک قدم نزدیک‌تر به پیشرفت زبان‌آموزانتان.','A little more progress for every learner, every day.')}</p></div><div className="actions"><button className="btn" onClick={addStudent}><Users/>{t('افزودن زبان‌آموز','Add student')}</button><button className="btn primary" onClick={()=>addSession()}><Plus/>{t('کلاس جدید','New class')}</button></div></div>
 {w.demo&&<div className="welcome-strip"><Info size={16}/><span>{t('در حال مشاهده داده‌های نمونه هستید؛ امکانات را امتحان کنید.','You’re exploring sample data. Try out your workspace.')}</span><button onClick={()=>setResetOpen(true)}>{t('شروع با فضای خالی','Start with an empty workspace')} <span aria-hidden="true">←</span></button></div>}
 <div className="metrics"><Metric label={t('زبان‌آموزان فعال','Active students')} value={n(w.students.length)} foot={t('در مسیر یادگیری با شما','Learning and growing with you')} Icon={Users}/><Metric label={t('کلاس‌های این هفته','Classes this week')} value={n(weekSessions.length)} foot={n(weekSessions.filter(s=>s.status==='held').length)+' '+t('جلسه برگزار شده','classes completed')} Icon={CalendarDays}/><Metric label={t('زمان آموزش این هفته','Teaching this week')} value={n(totalHours)} unit={t('ساعت','hours')} foot={t('مجموع جلسات برگزارشده و پیش رو','Completed and upcoming sessions')} Icon={Clock}/><Metric label={t('شهریه تسویه‌نشده','Outstanding fees')} value={<span className="money-value">{formatTotals(unpaid,lang)}</span>} foot={n(unpaid.length)+' '+t('جلسه در انتظار تسویه','sessions awaiting settlement')} Icon={Wallet} emphasis/></div>
 <div className="overview-grid"><div><section className="panel"><SectionHead title={t('برنامه کلاس‌ها','Your schedule')} sub={date(selectedDay,{month:'long',year:'numeric'})} action={<div className="week-controls"><button className="icon-button" onClick={()=>setSelectedDay(addDays(selectedDay,-7))} aria-label={t('هفته قبل','Previous week')}><ChevronRight/></button><button className="btn compact" onClick={()=>setSelectedDay(today)}>{t('امروز','Today')}</button><button className="icon-button" onClick={()=>setSelectedDay(addDays(selectedDay,7))} aria-label={t('هفته بعد','Next week')}><ChevronLeft/></button></div>}/><WeekStrip selected={selectedDay} onSelect={setSelectedDay} sessions={w.sessions}/><div className="schedule-list">{w.sessions.filter(s=>s.date===selectedDay).sort((a,b)=>a.time.localeCompare(b.time)).map(s=><SessionRow key={s.id} s={s} w={w} onEdit={editSession}/>)}{!w.sessions.some(s=>s.date===selectedDay)&&<Empty text={t('برای این روز کلاسی ندارید.','No classes planned for this day.')} action={<button className="btn soft" onClick={()=>addSession()}><Plus/>{t('برنامه‌ریزی کلاس','Schedule a class')}</button>}/>}</div><div className="panel-footer"><Link className="text-link" href="/schedule">{t('مشاهده تقویم کامل','View full schedule')}<ChevronLeft/></Link></div></section>
 <section className="panel overview-students"><SectionHead title={t('زبان‌آموزان شما','Your students')} action={<Link className="text-link" href="/students">{t('مشاهده همه','View all')}<ChevronLeft/></Link>}/>{w.students.length?<RosterTable students={w.students.slice(0,4)} w={w}/>:<Empty text={t('اولین زبان‌آموزتان را اضافه کنید.','Add your first student.')} action={<button className="btn primary" onClick={addStudent}><Plus/>{t('افزودن زبان‌آموز','Add student')}</button>}/>}</section></div>
 <div className="stack"><section className="panel"><SectionHead title={t('ریتم آموزش شما','Your teaching rhythm')} action={<span className="badge gray">{t('این هفته','This week')}</span>}/><div className="panel-body"><div className="month-summary"><span className="month-number">{n(weekSessions.length)}</span><div><span className="small">{t('جلسه آموزشی','teaching sessions')}</span><p className="stat-subtitle">{t('توزیع کلاس‌ها در طول هفته','Your week, at a glance')}</p></div></div><div className="chart-wrap" role="img" aria-label={t('نمودار تعداد کلاس‌ها در هر روز هفته','Number of classes each day this week')}>{Array.from({length:7},(_,i)=>{const d=addDays(start,i),count=weekSessions.filter(s=>s.date===d).length,max=Math.max(1,...Array.from({length:7},(_,j)=>weekSessions.filter(s=>s.date===addDays(start,j)).length));return <div className="bar-column" key={d} title={date(d,{weekday:'long'})+': '+n(count)}><span className="small muted">{count?n(count):''}</span><div className="bar" style={{height:count/max*96+'px'}}/><small>{date(d,{weekday:'narrow'})}</small></div>})}</div><div className="chart-caption"><span><i className="chart-key"/>{t('تعداد جلسات','Sessions')}</span><Link className="text-link" href="/schedule">{t('جزئیات','Details')}<ArrowUpLeft/></Link></div></div></section>
 <section className="panel"><SectionHead title={t('نگاهی به پیشرفت‌ها','Learning in focus')} sub={t('آخرین میانگین ارزیابی مهارت‌ها','Latest skill assessment averages')}/><div className="panel-body">{w.students.slice(0,3).map(s=><Link key={s.id} href={'/students/'+s.id} className="mini-session"><Avatar student={s}/><div className="mini-session-info"><strong>{s.name}</strong><p>{t('سطح','Level')} <span className="ltr">{s.level}</span></p></div><span className="badge">{n(average(s.skills))} / {n(9)}</span></Link>)}{!w.students.length&&<Empty text={t('ارزیابی‌ها اینجا نمایش داده می‌شوند.','Assessments will appear here.')}/>}</div></section></div></div></>}
 {route==='students'&&!studentId&&<><PageHeading title={t('زبان‌آموزان شما','Your students')} subtitle={t('هر زبان‌آموز، یک مسیر منحصربه‌فرد.','A unique learning journey for every student.')} action={<button className="btn primary" onClick={addStudent}><Plus/>{t('افزودن زبان‌آموز','Add student')}</button>}/><div className="filters"><div className="search-field"><Search/><input aria-label={t('جستجوی زبان‌آموز','Search students')} placeholder={t('جستجوی نام یا ایمیل…','Search name or email…')} value={search} onChange={e=>setSearch(e.target.value)}/></div><Choice label={t('فیلتر سطح','Filter by level')} value={level} onChange={setLevel} options={[["all",t('همه سطوح','All levels')],...levels.map(l=>[l,l] as const)]}/><span className="small muted">{n(visibleStudents.length)} {t('زبان‌آموز','students')}</span></div><div className="student-grid">{visibleStudents.map(s=><Link className="student-card" href={'/students/'+s.id} key={s.id}><div className="student-card-top"><Avatar student={s}/><div style={{flex:1}}><h3>{s.name}</h3><small>{t('زبان انگلیسی','English learner')}</small></div><span className="badge purple">{s.level}</span></div>{skillKeys.map(k=><div className="skill-progress-row" key={k}><span>{t(skillNames[k][0],skillNames[k][1])}</span><Progress value={s.skills[k]/9*100} aria-label={t(skillNames[k][0],skillNames[k][1])}/><b className="ltr">{n(s.skills[k])}</b></div>)}<div className="student-card-foot"><span className="small muted">{formatMoney(s.rate,s.currency,lang)} {t('/ جلسه','/ class')}</span><span className="text-link">{t('پرونده','Profile')}<ChevronLeft/></span></div></Link>)}</div>{!visibleStudents.length&&<Empty text={search||level!=='all'?t('زبان‌آموزی با این مشخصات پیدا نشد.','No students match your search.'):t('هنوز زبان‌آموزی ندارید.','No students yet.')} action={<button className="btn primary" onClick={addStudent}><Plus/>{t('افزودن زبان‌آموز','Add student')}</button>}/>}</>}
 {route==='students'&&studentId&&(student?<StudentDetail student={student} w={w} save={save} busy={busy} onEdit={()=>setModal({type:'student',student})} onSession={()=>addSession(student)} onAssessment={()=>setModal({type:'assessment',student})} editSession={editSession}/>:<Empty text={t('این زبان‌آموز پیدا نشد.','Student not found.')} action={<Link className="btn" href="/students">{t('بازگشت به زبان‌آموزان','Back to students')}</Link>}/>)}
 {route==='schedule'&&<><PageHeading title={t('برنامه کلاس‌ها','Class schedule')} subtitle={t('هفته‌تان را با خیال آسوده برنامه‌ریزی کنید.','Make room for a well-planned week.')} action={<button className="btn primary" onClick={()=>addSession()}><Plus/>{t('کلاس جدید','New class')}</button>}/><div className="panel"><SectionHead title={date(weekStart(selectedDay))+' — '+date(addDays(weekStart(selectedDay),6),{day:'numeric',month:'long',year:'numeric'})} action={<div className="week-controls"><button className="icon-button" onClick={()=>setSelectedDay(addDays(selectedDay,-7))} aria-label={t('هفته قبل','Previous week')}><ChevronRight/></button><button className="btn compact" onClick={()=>setSelectedDay(today)}>{t('امروز','Today')}</button><button className="icon-button" onClick={()=>setSelectedDay(addDays(selectedDay,7))} aria-label={t('هفته بعد','Next week')}><ChevronLeft/></button></div>}/><WeekStrip selected={selectedDay} onSelect={setSelectedDay} sessions={w.sessions}/>{Array.from({length:7},(_,i)=>addDays(weekStart(selectedDay),i)).map(d=>{const sessions=w.sessions.filter(s=>s.date===d).sort((a,b)=>a.time.localeCompare(b.time));return <section className="agenda-day" key={d}><div style={{display:'flex',justifyContent:'space-between',gap:12}}><h3>{date(d,{weekday:'long',day:'numeric',month:'long'})} {d===today&&<span className="badge">{t('امروز','Today')}</span>}</h3>{d>=today&&<button className="text-link" onClick={()=>{setSelectedDay(d);addSession()}}><Plus size={15}/>{t('کلاس جدید','Add class')}</button>}</div>{sessions.length?sessions.map(s=><SessionRow s={s} w={w} onEdit={editSession} key={s.id}/>):<p className="small muted" style={{padding:'10px 0'}}>{t('بدون کلاس برنامه‌ریزی‌شده','No classes scheduled')}</p>}</section>})}</div></>}
 {route==='finance'&&<><PageHeading title={t('شهریه و تسویه','Fees & settlements')} subtitle={t('حساب کلاس‌ها، همیشه روشن و مرتب.','A clear view of every class and payment.')}/><Finance w={w} save={save} busy={busy}/></>}
 {route==='messages'&&<><PageHeading title={t('گفتگوها','Conversations')} subtitle={t('یادداشت‌ها و پیش‌نویس پیام‌های هر زبان‌آموز، در یک جا.','Keep student notes and message drafts together.')}/><Messages w={w} save={save} busy={busy}/></>}
 {route==='settings'&&<><PageHeading title={t('تنظیمات','Settings')} subtitle={t('این فضای کار را برای خودتان تنظیم کنید.','Make this workspace your own.')}/><SettingsView w={w} save={save} busy={busy} onReset={()=>setResetOpen(true)}/></>}
 {route==='studio'&&<TeacherStudio lang={lang} workspaceProfile={w.profile}/>}
 {route==='admin'&&(isAdmin?<AdminInbox lang={lang}/>:<Empty text={t('این بخش فقط برای مدیر سایت است.','This section is for the site administrator.')}/>)}
 {!labels[route]&&<Empty text={t('صفحه مورد نظر پیدا نشد.','This page could not be found.')} action={<Link className="btn" href="/dashboard">{t('بازگشت به پیشخوان','Back to overview')}</Link>}/>}
 <footer className="dashboard-bottom"><span dir="ltr">MahELA © {new Date().getFullYear()}</span><span className="icon-with-text"><ShieldCheck size={13}/>{w.demo?t('فضای نمونه · ویژه معلم','Sample workspace · Teacher view'):t('فضای شخصی معلم','Your private teaching workspace')}</span></footer></>}
 </main></div>
 <Dialog open={!!modal} onOpenChange={open=>{if(!open&&!busy)setModal(null)}}><DialogContent className="modal" dir={lang==='fa'?'rtl':'ltr'}><DialogHeader><DialogTitle>{modal?.type==='student'?(modal.student?t('ویرایش زبان‌آموز','Edit student'):t('زبان‌آموز جدید','New student')):modal?.type==='session'?(modal.session?t('مدیریت کلاس','Manage class'):t('برنامه‌ریزی کلاس','Schedule a class')):t('ارزیابی جدید','New assessment')}</DialogTitle><DialogDescription>{modal?.type==='student'?t('اطلاعات و برنامه آموزشی زبان‌آموز را وارد کنید.','Add contact details and learning preferences.'):modal?.type==='session'?t('زمان، شیوه برگزاری و جزئیات کلاس را مشخص کنید.','Set a time, class format and session details.'):t('نمره‌های IELTS از ۰ تا ۹، با گام نیم نمره.','IELTS band scores from 0 to 9, in half-point steps.')}</DialogDescription></DialogHeader>
 {modal?.type==='student'&&<StudentForm student={modal.student} w={w} busy={busy} onCancel={()=>setModal(null)} onSave={async s=>{const next={...w,students:modal.student?w.students.map(x=>x.id===s.id?s:x):[...w.students,s]};if(await save(next,t('اطلاعات زبان‌آموز ذخیره شد.','Student saved.')))setModal(null)}}/>}
 {modal?.type==='session'&&<SessionForm student={modal.student} session={modal.session} w={w} today={today} defaultDate={selectedDay>=today?selectedDay:today} busy={busy} onCancel={()=>setModal(null)} onSave={async s=>{const next={...w,sessions:modal.session?w.sessions.map(x=>x.id===s.id?s:x):[...w.sessions,s]};if(await save(next,t('کلاس ذخیره شد.','Class saved.')))setModal(null)}} onDelete={async()=>{if(await save({...w,sessions:w.sessions.filter(s=>s.id!==modal.session?.id)},t('جلسه حذف شد.','Session deleted.')))setModal(null)}}/>}
 {modal?.type==='assessment'&&modal.student&&<AssessmentForm student={modal.student} busy={busy} onCancel={()=>setModal(null)} onSave={async(skills,note)=>{const s=modal.student!;if(await save({...w,students:w.students.map(x=>x.id===s.id?{...x,skills}:x),assessments:[{id:uid(),studentId:s.id,date:new Date().toISOString(),skills,note},...w.assessments]},t('ارزیابی جدید ثبت شد.','Assessment saved.')))setModal(null)}}/>}
 </DialogContent></Dialog>
 <AlertDialog open={resetOpen} onOpenChange={setResetOpen}><AlertDialogContent dir={lang==='fa'?'rtl':'ltr'}><AlertDialogHeader><AlertDialogTitle>{t('شروع با فضای خالی؟','Start with an empty workspace?')}</AlertDialogTitle><AlertDialogDescription>{t('زبان‌آموزان، جلسات، ارزیابی‌ها و پیام‌های نمونه و تغییراتی که در فضای نمونه داده‌اید حذف می‌شوند. اطلاعات پروفایل شما حفظ می‌شود.','Sample students, sessions, assessments, messages and any edits made in sample mode will be removed. Your profile is preserved.')}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>{t('انصراف','Cancel')}</AlertDialogCancel><AlertDialogAction disabled={busy||!w.demo} onClick={async e=>{e.preventDefault();if(await save({...emptyWorkspace(),profile:w.profile},t('فضای کاری شما آماده است.','Your workspace is ready.'))){setResetOpen(false);router.push('/students')}}}>{t('شروع فضای کاری من','Start my workspace')}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
 <Toaster position={lang==='fa'?'bottom-left':'bottom-right'} richColors dir={lang==='fa'?'rtl':'ltr'} theme={dark?'dark':'light'}/></SidebarProvider></LocaleContext.Provider>
}
function PageHeading({title,subtitle,action}:{title:string,subtitle:string,action?:React.ReactNode}){return <div className="page-heading"><div><h1>{title}</h1><p>{subtitle}</p></div>{action&&<div className="actions">{action}</div>}</div>}

function Radar({skills}:{skills:Skills}){const {t}=useL();const c=160,r=100,point=(i:number,scale:number)=>{const a=-Math.PI/2+i*Math.PI/2;return `${c+Math.cos(a)*r*scale},${c+Math.sin(a)*r*scale}`};return <svg className="radar" viewBox="0 0 320 315" role="img" aria-label={t('نمودار مهارت‌های شنیداری، گفتاری، خواندن و نوشتاری','Listening, speaking, reading and writing skill chart')}>{[.25,.5,.75,1].map(s=><polygon key={s} points={skillKeys.map((_,i)=>point(i,s)).join(' ')} fill="none" stroke="var(--border)" strokeWidth="1.2"/>)}{skillKeys.map((k,i)=><line key={k} x1={c} y1={c} x2={point(i,1).split(',')[0]} y2={point(i,1).split(',')[1]} stroke="var(--border)"/>)}<polygon points={skillKeys.map((k,i)=>point(i,skills[k]/9)).join(' ')} fill="#58a68a33" stroke="#399979" strokeWidth="2.5"/>{skillKeys.map((k,i)=><circle key={k} cx={point(i,skills[k]/9).split(',')[0]} cy={point(i,skills[k]/9).split(',')[1]} r="4" fill="#399979" stroke="var(--card)" strokeWidth="2"/>)}<text x="160" y="34" textAnchor="middle">{t(...skillNames.listening)}</text><text x="285" y="164" textAnchor="middle">{t(...skillNames.speaking)}</text><text x="160" y="289" textAnchor="middle">{t(...skillNames.reading)}</text><text x="36" y="164" textAnchor="middle">{t(...skillNames.writing)}</text></svg>}
type Save=(next:Workspace,message?:string)=>Promise<boolean>;
function StudentDetail({student:s,w,save,busy,onEdit,onSession,onAssessment,editSession}:{student:Student,w:Workspace,save:Save,busy:boolean,onEdit:()=>void,onSession:()=>void,onAssessment:()=>void,editSession:(s:Session)=>void}){const {t,n,date,lang}=useL();const [tab,setTab]=useState('overview');const sessions=w.sessions.filter(x=>x.studentId===s.id).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));const assessments=w.assessments.filter(x=>x.studentId===s.id).sort((a,b)=>b.date.localeCompare(a.date));return <><Link className="text-link" href="/students" style={{marginBottom:20}}><ArrowLeft size={16}/>{t('بازگشت به زبان‌آموزان','Back to students')}</Link><section className="panel detail-profile"><Avatar student={s} large/><div className="profile-data"><h1>{s.name}</h1><div style={{display:'flex',gap:9,alignItems:'center',marginTop:6}}><span className="badge purple">{s.level}</span><span className="small muted">{t('زبان‌آموز انگلیسی','English learner')}</span></div><div className="detail-contact"><span><Mail/><bdi>{s.email}</bdi></span><span><Phone/><bdi>{n(s.phone)}</bdi></span></div></div><button className="btn" onClick={onEdit}><Pencil/>{t('ویرایش پرونده','Edit profile')}</button></section><Tabs value={tab} onValueChange={setTab} dir={lang==='fa'?'rtl':'ltr'}><TabsList className="detail-tabs">{[['overview',t('نمای کلی','Overview')],['skills',t('مهارت‌ها','Skills')],['schedule',t('برنامه کلاس‌ها','Schedule')],['finance',t('شهریه','Finance')],['messages',t('گفتگو','Messages')]].map(([v,l])=><TabsTrigger value={v} key={v}>{l}</TabsTrigger>)}</TabsList>
 <TabsContent value="overview"><div className="metrics stats-three"><Metric label={t('نرخ هر جلسه','Session rate')} value={n(s.rate)} unit={currencyName(s.currency,lang)} foot={n(s.duration)+' '+t('دقیقه آموزش','minutes of teaching')} Icon={Wallet}/><Metric label={t('جلسات برگزارشده','Completed classes')} value={n(sessions.filter(x=>x.status==='held').length)} foot={t('از شروع دوره آموزشی','Since the beginning of the course')} Icon={CalendarCheck}/><Metric label={t('همراه شما از','Learning since')} value={date(s.since,{month:'short',day:'numeric'})} foot={date(s.since,{year:'numeric'})} Icon={GraduationCap}/></div><div className="skills-layout"><section className="panel"><SectionHead title={t('تصویر مهارت‌ها','Skills at a glance')} action={<button className="text-link" onClick={onAssessment}><Plus size={15}/>{t('ارزیابی جدید','New assessment')}</button>}/><Radar skills={s.skills}/></section><section className="panel"><SectionHead title={t('آخرین ارزیابی','Latest assessment')} sub={assessments[0]?date(assessments[0].date):t('هنوز ارزیابی ثبت نشده','No assessment yet')}/><div className="panel-body">{skillKeys.map(k=>{const Icon=skillIcons[k];return <div className="skill-input" key={k}><span className="icon-with-text"><Icon/>{t(skillNames[k][0],skillNames[k][1])}</span><span className="ltr"><b>{n(s.skills[k])}</b><span className="muted"> / {n(9)}</span></span></div>})}{assessments[0]?.note&&<p className="notes-line" style={{marginTop:20}}>{assessments[0].note}</p>}</div></section></div></TabsContent>
 <TabsContent value="skills"><div className="skills-layout"><section className="panel"><SectionHead title={t('مهارت‌های زبان','Language skills')} action={<button className="btn primary compact" onClick={onAssessment}><Plus/>{t('ارزیابی جدید','New assessment')}</button>}/><Radar skills={s.skills}/></section><section className="panel"><SectionHead title={t('سابقه ارزیابی‌ها','Assessment history')} sub={t('نمره‌های IELTS از ۹','IELTS bands, out of 9')}/><div className="panel-body">{assessments.map(a=><article className="assessment-item" key={a.id}><h3 className="small">{date(a.date,{day:'numeric',month:'long',year:'numeric'})}</h3><div className="assessment-values">{skillKeys.map(k=><span className="badge gray" key={k}>{t(skillNames[k][0],skillNames[k][1])} · {n(a.skills[k])}</span>)}</div>{a.note&&<p className="notes-line">{a.note}</p>}</article>)}{!assessments.length&&<Empty text={t('اولین ارزیابی را ثبت کنید.','Record the first assessment.')}/>}</div></section></div></TabsContent>
 <TabsContent value="schedule"><section className="panel"><SectionHead title={t('همه جلسات','All classes')} action={<button className="btn primary compact" onClick={onSession}><Plus/>{t('کلاس جدید','New class')}</button>}/><div className="panel-body">{sessions.map(x=><div key={x.id}><p className="small muted" style={{paddingTop:14}}>{date(x.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p><SessionRow s={x} w={w} onEdit={editSession}/>{x.note&&<p className="notes-line">{x.note}</p>}</div>)}{!sessions.length&&<Empty text={t('هنوز کلاسی ثبت نشده است.','No classes recorded yet.')}/>}</div></section></TabsContent>
 <TabsContent value="finance"><Finance key={s.id} w={w} save={save} busy={busy} studentId={s.id}/></TabsContent><TabsContent value="messages"><Messages w={w} save={save} busy={busy} studentId={s.id}/></TabsContent></Tabs></>}

function Finance({w,save,busy,studentId}:{w:Workspace,save:Save,busy:boolean,studentId?:string}){const {t,n,date,lang}=useL();const router=useRouter();const [selected,setSelected]=useState<string[]>([]);const [confirm,setConfirm]=useState(false);const sessions=w.sessions.filter(s=>!studentId||s.studentId===studentId);const due=sessions.filter(s=>billable(s)&&!s.paid).sort((a,b)=>b.date.localeCompare(a.date));const paid=sessions.filter(s=>s.paid).sort((a,b)=>b.paidAt.localeCompare(a.paidAt));const chosen=due.filter(s=>selected.includes(s.id));const amount=formatTotals(chosen,lang);const total=formatTotals(due,lang);
 async function settle(){const now=new Date().toISOString();if(await save({...w,sessions:w.sessions.map(s=>chosen.some(x=>x.id===s.id)?{...s,paid:true,paidAt:now}:s)},t('دریافت شهریه ثبت شد.','Payment recorded.'))){setSelected([]);setConfirm(false)}}
 async function requestPayment(){const drafts=Array.from(new Set(chosen.map(s=>s.studentId))).map(id=>{const items=chosen.filter(s=>s.studentId===id),sum=formatTotals(items,lang),student=w.students.find(s=>s.id===id);return {id:uid(),studentId:id,date:new Date().toISOString(),direction:'out' as const,sample:false,text:t(`سلام ${student?.name}، شهریه ${n(items.length)} جلسه شما، جمعاً ${sum}، آماده تسویه است.\nجلسات: ${items.map(s=>date(s.date)+' '+n(s.time)).join('، ')}\nسپاس از همراهی شما.`,`Hello ${student?.name}, your ${items.length} classes have an outstanding balance of ${sum}.\nClasses: ${items.map(s=>date(s.date)+' '+s.time).join(', ')}\nThank you.`)}});if(await save({...w,messages:[...w.messages,...drafts]},t('پیش‌نویس درخواست تسویه ذخیره شد.','Payment request draft saved.')))router.push('/messages')}
 return <><div className="metrics stats-three"><Metric label={t('مانده قابل تسویه','Outstanding balance')} value={<span className="money-value">{total}</span>} foot={n(due.length)+' '+t('جلسه تسویه‌نشده','unpaid sessions')} Icon={Wallet} emphasis/><Metric label={t('شهریه دریافت‌شده','Fees received')} value={<span className="money-value">{formatTotals(paid,lang)}</span>} foot={n(paid.length)+' '+t('جلسه تسویه‌شده','paid sessions')} Icon={CheckCheck}/><Metric label={t('جلسات مشمول شهریه','Billable classes')} value={n(sessions.filter(billable).length)} foot={t('برگزارشده یا لغوشده با شهریه','Completed or charged cancellations')} Icon={CalendarCheck}/></div>
 <section className="panel"><SectionHead title={t('جلسات در انتظار تسویه','Awaiting settlement')} sub={t('جلسه‌های موردنظر را برای ثبت دریافت انتخاب کنید.','Select the sessions you have received payment for.')}/><div className="panel-body"><div className="balance-summary"><div><p>{n(chosen.length)} {t('جلسه انتخاب شده','sessions selected')}</p><strong>{amount}</strong></div><div className="actions"><button className="btn" disabled={!chosen.length||busy} onClick={requestPayment}><MessageSquare/>{t('پیش‌نویس درخواست تسویه','Draft payment request')}</button><button className="btn primary" disabled={!chosen.length||busy} onClick={()=>setConfirm(true)}><Check/>{t('ثبت دریافت شهریه','Record payment')}</button></div></div></div>
 {due.length?<Table className="roster-table finance-table"><TableHeader><TableRow><TableHead><Checkbox checked={due.length>0&&chosen.length===due.length} onCheckedChange={v=>setSelected(v?due.map(s=>s.id):[])} aria-label={t('انتخاب همه جلسات','Select all sessions')}/></TableHead><TableHead>{t('زبان‌آموز / جلسه','Student / class')}</TableHead><TableHead>{t('وضعیت','Status')}</TableHead><TableHead>{t('شهریه و واحد پول','Fee & currency')}</TableHead></TableRow></TableHeader><TableBody>{due.map(s=>{const student=w.students.find(x=>x.id===s.studentId);return <TableRow key={s.id}><TableCell><Checkbox checked={selected.includes(s.id)} onCheckedChange={v=>setSelected(v?[...selected,s.id]:selected.filter(id=>id!==s.id))} aria-label={t('انتخاب جلسه ','Select class ')+student?.name+' '+date(s.date)}/></TableCell><TableCell><div className="student-cell"><Avatar student={student}/><span><strong>{student?.name}</strong><small>{date(s.date)} · {n(s.time)}</small></span></div></TableCell><TableCell><Status session={s}/></TableCell><TableCell>{formatMoney(s.rate,s.currency,lang)}</TableCell></TableRow>})}</TableBody></Table>:<Empty text={t('همه‌چیز مرتب است؛ شهریه تسویه‌نشده‌ای ندارید.','All caught up. There are no outstanding fees.')}/>}</section>
 <section className="panel" style={{marginTop:22}}><SectionHead title={t('سابقه دریافت‌ها','Payment history')}/>{paid.length?<Table className="roster-table"><TableHeader><TableRow><TableHead>{t('زبان‌آموز','Student')}</TableHead><TableHead>{t('تاریخ جلسه','Class date')}</TableHead><TableHead>{t('تاریخ ثبت دریافت','Payment date')}</TableHead><TableHead>{t('مبلغ و واحد پول','Amount & currency')}</TableHead></TableRow></TableHeader><TableBody>{paid.map(s=><TableRow key={s.id}><TableCell>{w.students.find(x=>x.id===s.studentId)?.name}</TableCell><TableCell>{date(s.date)}</TableCell><TableCell>{date(s.paidAt)}</TableCell><TableCell><span className="badge">{formatMoney(s.rate,s.currency,lang)}</span></TableCell></TableRow>)}</TableBody></Table>:<Empty text={t('هنوز دریافتی ثبت نشده است.','No payments recorded yet.')}/>}</section>
 <AlertDialog open={confirm} onOpenChange={setConfirm}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{t('دریافت شهریه ثبت شود؟','Record this payment?')}</AlertDialogTitle><AlertDialogDescription>{t(`دریافت ${amount} برای ${n(chosen.length)} جلسه ثبت می‌شود. تنها پس از دریافت وجه تأیید کنید؛ این کار پرداخت بانکی انجام نمی‌دهد و جلسات تسویه‌شده قابل ویرایش نخواهند بود.`,`Record ${amount} for ${chosen.length} classes. Confirm only after receiving payment. This does not charge a bank account, and settled classes will be locked.`)}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>{t('انصراف','Cancel')}</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={e=>{e.preventDefault();settle()}}>{t('بله، دریافت شد','Yes, payment received')}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>}

function Messages({w,save,busy,studentId}:{w:Workspace,save:Save,busy:boolean,studentId?:string}){const {t,n,date}=useL();const [active,setActive]=useState(studentId||w.students[0]?.id||'');const [draft,setDraft]=useState('');const student=w.students.find(s=>s.id===active);const messages=w.messages.filter(m=>m.studentId===active).sort((a,b)=>a.date.localeCompare(b.date));const latest=messages.filter(m=>m.direction==='out').at(-1)?.text||'';
 async function add(e:React.FormEvent){e.preventDefault();if(!draft.trim()||!student)return;if(await save({...w,messages:[...w.messages,{id:uid(),studentId:active,text:draft.trim(),date:new Date().toISOString(),direction:'out',sample:false}]},t('پیش‌نویس ذخیره شد.','Draft saved.')))setDraft('')}
 async function copy(){try{await navigator.clipboard.writeText(draft||latest);toast.success(t('متن پیام کپی شد.','Message copied.'))}catch{toast.error(t('امکان کپی خودکار وجود ندارد؛ متن را انتخاب و کپی کنید.','Select the text and copy it manually.'))}}
 if(!w.students.length)return <section className="panel"><Empty text={t('برای ثبت پیام، ابتدا زبان‌آموز اضافه کنید.','Add a student to start a conversation.')} action={<Link className="btn" href="/students">{t('زبان‌آموزان','Students')}</Link>}/></section>;
 return <section className="panel messages-layout" style={studentId?{gridTemplateColumns:'1fr'}:{}}>{!studentId&&<aside className="conversation-list" aria-label={t('گفتگوهای زبان‌آموزان','Student conversations')}>{w.students.map(s=><button className={'conversation-item '+(s.id===active?'active':'')} key={s.id} onClick={()=>{setActive(s.id);setDraft('')}}><Avatar student={s}/><div><strong className="small">{s.name}</strong><p>{n(w.messages.filter(m=>m.studentId===s.id).length)} {t('پیام و یادداشت','messages & notes')}</p></div></button>)}</aside>}<div className="conversation-body"><div className="conversation-title"><Avatar student={student}/><div style={{flex:1}}><h3>{student?.name}</h3><p className="small muted">{t('یادداشت و پیش‌نویس پیام','Notes & message drafts')}</p></div><span className="badge gray">{t('ذخیره‌شده','Saved')}</span></div><div className="chat-area">{messages.map(m=><article key={m.id} className={'chat-message '+(m.direction==='in'?'in':'')}><p>{m.text}</p><small>{m.sample?t('نمونه گفتگو','Sample conversation'):t('پیش‌نویس','Draft')} · {date(m.date,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></article>)}{!messages.length&&<Empty text={t('اولین یادداشت یا پیام را بنویسید.','Write your first note or draft.')}/>}</div><form className="message-form" onSubmit={add}><textarea value={draft} onChange={e=>setDraft(e.target.value)} maxLength={4000} aria-label={t('متن پیام','Message text')} placeholder={t('پیامی برای زبان‌آموز بنویسید…','Write a message for your student…')}/><button className="btn primary" disabled={busy||!draft.trim()}><PenLine/>{t('ثبت پیش‌نویس','Save draft')}</button><button className="icon-button" type="button" onClick={copy} disabled={!draft&&!latest} aria-label={t('کپی متن پیام','Copy message')}><Copy/></button>{student&&(draft||latest)&&<a className="icon-button" href={`mailto:${encodeURIComponent(student.email)}?subject=${encodeURIComponent('MahELA — '+t('پیام معلم','Teacher message'))}&body=${encodeURIComponent(draft||latest)}`} aria-label={t('باز کردن در برنامه ایمیل','Open in your email app')}><Mail/></a>}</form><p className="message-disclaimer">{t('پیام‌ها اینجا ذخیره می‌شوند. برای ارسال، متن را کپی کنید یا با آیکن ایمیل در برنامه ایمیل خود باز کنید. ارسال مستقیم و ورود مستقل زبان‌آموز هنوز فعال نیست.','Messages are saved here. Copy the text or open it in your email app to send. Direct delivery and separate student sign-in are not enabled.')}</p></div></section>}

function SettingsView({w,save,busy,onReset}:{w:Workspace,save:Save,busy:boolean,onReset:()=>void}){const {t}=useL();const [profile,setProfile]=useState(w.profile);const [uploading,setUploading]=useState(false);const [error,setError]=useState('');const set=(key:keyof Workspace['profile'],value:string)=>setProfile({...profile,[key]:value});
 async function upload(e:React.ChangeEvent<HTMLInputElement>){const f=e.target.files?.[0];if(!f)return;setUploading(true);setError('');try{if(f.size>5*1024*1024)throw Error(t('حداکثر حجم عکس ۵ مگابایت است.','Maximum photo size is 5 MB.'));const r=await fetch('/api/photo',{method:'POST',headers:{'Content-Type':f.type},body:f}),j=await r.json() as {url:string;error?:string};if(!r.ok)throw Error(j.error);const next={...profile,photo:j.url};setProfile(next);await save({...w,profile:next},t('عکس پروفایل ذخیره شد.','Profile photo saved.'))}catch(e){setError((e as Error).message)}finally{setUploading(false)}}
 return <div className="settings-layout"><section className="panel"><SectionHead title={t('پروفایل معلم','Teacher profile')} sub={t('اطلاعات تماس و معرفی آموزشی شما','Your contact details and teaching profile')}/><form className="settings-form" onSubmit={async e=>{e.preventDefault();setError('');await save({...w,profile},t('تنظیمات ذخیره شد.','Settings saved.'))}}><div className="profile-upload"><Avatar name={profile.name} photo={profile.photo} large/><div><label className="btn" htmlFor="photo-upload"><Upload size={17}/>{uploading?t('در حال بارگذاری…','Uploading…'):t('تغییر عکس','Upload photo')}</label><input id="photo-upload" type="file" className="sr-only" accept="image/png,image/jpeg,image/webp" disabled={uploading||busy} onChange={upload}/><p className="small muted" style={{marginTop:8}}>{t('JPG، PNG یا WEBP · حداکثر ۵ مگابایت','JPG, PNG or WEBP · up to 5 MB')}</p>{profile.photo&&<button className="text-link" type="button" onClick={()=>set('photo','')}>{t('حذف عکس','Remove photo')}</button>}</div></div><div className="form-grid"><Field id="profile-name" label={t('نام و نام خانوادگی','Full name')}><input id="profile-name" required minLength={2} maxLength={100} value={profile.name} onChange={e=>set('name',e.target.value)}/></Field><Field id="profile-email" label={t('ایمیل','Email')}><input id="profile-email" type="email" dir="ltr" value={profile.email} onChange={e=>set('email',e.target.value)}/></Field><Field id="profile-phone" label={t('شماره تماس','Phone number')}><input id="profile-phone" dir="ltr" value={profile.phone} maxLength={30} onChange={e=>set('phone',digits(e.target.value))}/></Field><Field id="profile-specialty" label={t('حوزه تدریس','Teaching specialty')}><input id="profile-specialty" value={profile.specialization} maxLength={100} onChange={e=>set('specialization',e.target.value)}/></Field><Field id="profile-bio" label={t('درباره من','About me')} wide><textarea id="profile-bio" value={profile.bio} maxLength={1500} onChange={e=>set('bio',e.target.value)} placeholder={t('درباره شیوه تدریس و تجربه‌تان بنویسید…','A little about your teaching style and experience…')}/></Field><Field id="profile-currency" label={t('واحد پول پیش‌فرض کلاس‌ها','Default class currency')} wide><Choice id="profile-currency" value={profile.currency} onChange={v=>set('currency',v)} options={[["TOMAN",t('تومان','Toman')],["USD",t('دلار آمریکا','US dollar')]]}/><small>{t('برای زبان‌آموزان جدید؛ مبلغ و واحد پول سوابق تغییر نمی‌کند. نرخ عمومی را در پرتفولیو تنظیم کنید.','For new students; existing fees retain their currency. Set public pricing in your portfolio.')}</small></Field><Field id="profile-calendar" label={t('نمایش تقویم','Calendar display')} wide><Choice value={profile.calendar} onChange={v=>set('calendar',v)} id="profile-calendar" options={[["auto",t('خودکار بر اساس زبان','Automatic, based on language')],["persian",t('هجری شمسی','Persian (Jalali)')],["gregory",t('میلادی','Gregorian')]]}/></Field></div>{error&&<div className="form-error" role="alert">{error}</div>}<div className="form-actions"><button className="btn primary" disabled={busy||uploading}><Check/>{t('ذخیره تغییرات','Save changes')}</button></div></form></section><section className="panel"><SectionHead title={t('دسترسی به حساب','Account access')}/><div className="panel-body"><p className="small muted">{t('ورود امن این فضای شخصی با حساب ChatGPT شما مدیریت می‌شود. رمز عبور جداگانه‌ای در این سایت نگهداری نمی‌شود.','Your private workspace uses your ChatGPT account to sign in. This site does not store a separate password.')}</p><a className="btn" href="/signout-with-chatgpt?return_to=/" target="_top" style={{marginTop:18}}><LogOut/>{t('خروج از حساب','Sign out')}</a></div></section>{w.demo&&<section className="panel"><SectionHead title={t('داده‌های نمونه','Sample data')}/><div className="panel-body"><p className="small muted">{t('پس از آشنایی با امکانات، نمونه‌ها را حذف کنید و زبان‌آموزان خودتان را اضافه کنید.','When you’re ready, remove the sample records and add your own students.')}</p><button className="btn" style={{marginTop:16}} onClick={onReset}>{t('شروع با فضای خالی','Start with an empty workspace')}</button></div></section>}</div>}

function Field({id,label,children,wide=false}:{id:string,label:string,children:React.ReactNode,wide?:boolean}){return <div className={'field '+(wide?'wide':'')}><label htmlFor={id}>{label}</label>{children}</div>}
function digits(value:string){return value.replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))}
function FormActions({busy,onCancel,disabled=false}:{busy:boolean,onCancel:()=>void,disabled?:boolean}){const {t}=useL();return <div className="form-actions"><button type="button" className="btn" onClick={onCancel} disabled={busy}>{t('انصراف','Cancel')}</button><button className="btn primary" disabled={busy||disabled}>{busy?<LoaderCircle className="animate-spin"/>:<Check/>}{busy?t('در حال ذخیره…','Saving…'):t('ذخیره','Save')}</button></div>}
function StudentForm({student,w,busy,onSave,onCancel}:{student?:Student,w:Workspace,busy:boolean,onSave:(s:Student)=>Promise<void>,onCancel:()=>void}){const {t,n}=useL();const [s,setS]=useState<Student>(student||{id:uid(),name:'',email:'',phone:'',level:'A1',gender:'unspecified',currency:w.profile.currency,rate:w.profile.currency==='USD'?25:250000,duration:60,since:dateKey(new Date()),skills:{listening:0,speaking:0,reading:0,writing:0},tone:w.students.length%5});const [error,setError]=useState('');const set=(key:keyof Student,value:unknown)=>setS({...s,[key]:value});return <form onSubmit={async e=>{e.preventDefault();setError('');if(w.students.some(x=>x.id!==s.id&&x.email.toLowerCase()===s.email.toLowerCase())){setError(t('این ایمیل قبلاً ثبت شده است.','This email is already in use.'));return}if(!/^\+?[\d\s()-]{8,22}$/.test(s.phone)){setError(t('شماره تماس معتبر وارد کنید.','Enter a valid phone number.'));return}await onSave({...s,name:s.name.trim(),email:s.email.trim().toLowerCase()})}}><div className="form-grid"><Field id="student-name" label={t('نام و نام خانوادگی *','Full name *')} wide><input id="student-name" value={s.name} autoComplete="name" required minLength={2} maxLength={100} onChange={e=>set('name',e.target.value)} placeholder={t('مثلاً سارا احمدی','e.g. Sara Ahmadi')}/></Field><Field id="student-email" label={t('ایمیل *','Email *')}><input id="student-email" value={s.email} type="email" autoComplete="email" required maxLength={200} dir="ltr" onChange={e=>set('email',e.target.value)} placeholder="name@example.com"/></Field><Field id="student-phone" label={t('شماره تماس *','Phone number *')}><input id="student-phone" value={s.phone} dir="ltr" autoComplete="tel" required maxLength={22} onChange={e=>set('phone',digits(e.target.value))} placeholder="0912 123 4567"/></Field><Field id="student-level" label={t('سطح زبان','Language level')}><Choice value={s.level} onChange={v=>set('level',v)} id="student-level" options={levels.map(l=>[l,l])}/></Field><Field id="student-gender" label={t('جنسیت','Gender')}><Choice value={s.gender} onChange={v=>set('gender',v)} id="student-gender" options={[["unspecified",t('مشخص نشده','Unspecified')],["female",t('زن / دختر','Female')],["male",t('مرد / پسر','Male')]]}/></Field><Field id="student-duration" label={t('مدت هر جلسه (دقیقه)','Class duration (minutes)')}><input id="student-duration" type="number" min={15} max={300} step={1} required value={s.duration} onChange={e=>set('duration',Number(e.target.value))}/></Field><Field id="student-currency" label={t('واحد پول','Currency')}><Choice id="student-currency" value={s.currency} onChange={v=>setS({...s,currency:v as Currency,rate:0})} options={[["TOMAN",t('تومان','Toman')],["USD",t('دلار آمریکا','US dollar')]]}/></Field><Field id="student-rate" label={t('شهریه هر جلسه','Fee per class')}><input id="student-rate" type="number" min={0} max={100000000} step={s.currency==='USD'?0.01:1} required value={s.rate} onChange={e=>set('rate',Number(e.target.value))}/><small>{t('تغییر نرخ فقط برای جلسات جدید است.','Rate changes apply to new sessions only.')}</small></Field></div>{error&&<div className="form-error" role="alert">{error}</div>}<FormActions busy={busy} onCancel={onCancel}/></form>}
function DateField({value,onChange,today,editing}:{value:string,onChange:(v:string)=>void,today:string,editing:boolean}){const {date,t}=useL();const days=useMemo(()=>{const start=editing?(value<addDays(today,-366)?value:addDays(today,-366)):today;const result:string[]=[];for(let d=start;d<=addDays(today,366);d=addDays(d,1)){result.push(d);if(result.length>4000)break}return result},[today,editing]);const monthLabel=(d:string)=>date(d,{month:'long',year:'numeric'});const groups=new Map<string,string[]>();for(const d of days){const key=monthLabel(d);groups.set(key,[...(groups.get(key)||[]),d])}const month=monthLabel(value);const currentDays=groups.get(month)||[value];return <div className="form-grid" style={{gap:12}}><Choice label={t('ماه کلاس','Class month')} value={month} onChange={v=>onChange(groups.get(v)![0])} options={[...groups.keys()].map(k=>[k,k])}/><Choice label={t('روز کلاس','Class day')} value={value} onChange={onChange} options={currentDays.map(d=>[d,date(d,{day:'numeric',weekday:'long'})])}/></div>}
function SessionForm({session,student,w,today,defaultDate,busy,onSave,onCancel,onDelete}:{session?:Session,student?:Student,w:Workspace,today:string,defaultDate:string,busy:boolean,onSave:(s:Session)=>Promise<void>,onCancel:()=>void,onDelete:()=>Promise<void>}){const {t,n,lang}=useL();const selected=student||w.students[0];const [s,setS]=useState<Session>(session||{id:uid(),studentId:selected.id,date:defaultDate,time:'09:00',duration:selected.duration,type:'online',status:'scheduled',cancelReason:'student',charge:false,note:'',rate:selected.rate,currency:selected.currency,paid:false,paidAt:''});const [error,setError]=useState('');const [remove,setRemove]=useState(false);const [hour,setHour]=useState(s.time.slice(0,2));const [minute,setMinute]=useState(s.time.slice(3));const [duration,setDuration]=useState(`${Math.floor(s.duration/60)}:${String(s.duration%60).padStart(2,'0')}`);const set=(key:keyof Session,value:unknown)=>setS({...s,[key]:value});
 return <><form onSubmit={async e=>{e.preventDefault();setError('');const h=Number(digits(hour)),m=Number(digits(minute)),match=digits(duration).match(/^(\d{1,2}):([0-5]\d)$/);if(!hour||!minute||!/^\d{1,2}$/.test(digits(hour))||!/^\d{1,2}$/.test(digits(minute))||h<0||h>23||m<0||m>59){setError(t('ساعت ۰ تا ۲۳ و دقیقه ۰ تا ۵۹ وارد کنید.','Enter an hour from 0–23 and minutes from 0–59.'));return}if(!match){setError(t('مدت کلاس را مانند ۱:۱۵ وارد کنید.','Enter the duration as 1:15.'));return}const mins=Number(match[1])*60+Number(match[2]);if(mins<15||mins>300){setError(t('مدت کلاس بین ۱۵ تا ۳۰۰ دقیقه باشد.','Duration must be 15–300 minutes.'));return}if(!session&&s.date<today){setError(t('کلاس جدید باید برای امروز یا آینده باشد.','New classes must be today or later.'));return}const next={...s,time:String(h).padStart(2,'0')+':'+String(m).padStart(2,'0'),duration:mins,charge:s.status==='cancelled'&&s.cancelReason==='teacher'?false:s.charge};try{validateWorkspace({...w,sessions:session?w.sessions.map(x=>x.id===s.id?next:x):[...w.sessions,next]},w)}catch(e){setError((e as Error).message);return}await onSave(next)}}>
 {session?.paid&&<div className="status-help">{t('این جلسه تسویه شده و برای حفظ سابقه مالی، قابل ویرایش نیست.','This class has been settled and is locked to preserve payment history.')}</div>}<fieldset disabled={session?.paid||busy} style={{border:0,padding:0,margin:0,minWidth:0}}><div className="form-grid"><Field id="session-student" label={t('زبان‌آموز *','Student *')} wide><Choice id="session-student" value={s.studentId} onChange={v=>{const x=w.students.find(st=>st.id===v)!;setS({...s,studentId:v,rate:x.rate,currency:x.currency,duration:x.duration});setDuration(`${Math.floor(x.duration/60)}:${String(x.duration%60).padStart(2,'0')}`)}} options={w.students.map(x=>[x.id,x.name])}/></Field><div className="field wide"><label>{t('تاریخ کلاس','Class date')}</label><DateField value={s.date} onChange={v=>set('date',v)} today={today} editing={!!session}/></div><div className="field"><label>{t('ساعت شروع','Start time')}</label><div style={{display:'flex',gap:8,alignItems:'center',direction:'ltr'}}><input value={hour} onChange={e=>setHour(digits(e.target.value))} inputMode="numeric" maxLength={2} aria-label={t('ساعت','Hour')} required placeholder="09"/><span>:</span><input value={minute} onChange={e=>setMinute(digits(e.target.value))} inputMode="numeric" maxLength={2} aria-label={t('دقیقه','Minute')} required placeholder="00"/></div></div><Field id="session-duration" label={t('مدت کلاس (ساعت:دقیقه)','Duration (hours:minutes)')}><input id="session-duration" value={duration} onChange={e=>setDuration(digits(e.target.value))} dir="ltr" required placeholder="1:00"/><small>{t('مثلاً ۱:۱۵ برای ۷۵ دقیقه','e.g. 1:15 for 75 minutes')}</small></Field><Field id="session-type" label={t('شیوه برگزاری','Class format')} wide><RadioGroup id="session-type" value={s.type} onValueChange={v=>set('type',v)} className="choice-grid"><label><RadioGroupItem value="online" id="class-online"/>{t('آنلاین','Online')}</label><label><RadioGroupItem value="in-person" id="class-in-person"/>{t('حضوری','In person')}</label></RadioGroup></Field>{session&&<Field id="session-status" label={t('وضعیت جلسه','Class status')} wide><Choice id="session-status" value={s.status} onChange={v=>set('status',v)} options={[["scheduled",t('برنامه‌ریزی‌شده','Scheduled')],["held",t('برگزارشده','Completed')],["cancelled",t('لغوشده','Cancelled')]]}/></Field>}{s.status==='cancelled'&&<Field id="session-reason" label={t('علت لغو','Cancellation reason')} wide><Choice id="session-reason" value={s.cancelReason} onChange={v=>setS({...s,cancelReason:v as Session['cancelReason'],charge:v==='teacher'?false:s.charge})} options={[["teacher",t('لغو از طرف معلم','Teacher cancelled')],["student",t('لغو از طرف زبان‌آموز','Student cancelled')],["no-show",t('غیبت زبان‌آموز','Student did not attend')]]}/>{s.cancelReason!=='teacher'?<label className="checkbox-line"><Checkbox checked={s.charge} onCheckedChange={v=>set('charge',!!v)}/>{t('شهریه این جلسه محاسبه شود','Charge for this class')}</label>:<small>{t('لغو از طرف معلم بدون شهریه است.','No fee applies when the teacher cancels.')}</small>}</Field>}<div className="field wide"><label>{t('نرخ ثبت‌شده این جلسه','Recorded fee for this class')}</label><strong>{formatMoney(s.rate,s.currency,lang)}</strong></div><Field id="session-note" label={t('یادداشت جلسه','Class note')} wide><textarea id="session-note" value={s.note} maxLength={2000} onChange={e=>set('note',e.target.value)} placeholder={t('موضوع درس، تمرین یا نکته‌ای برای جلسه…','Topic, homework or a note for the class…')}/></Field></div></fieldset>
 {error&&<div className="form-error" role="alert">{error}</div>}<FormActions busy={busy} onCancel={onCancel} disabled={session?.paid}/>{session&&!session.paid&&<button className="text-link" style={{color:'var(--destructive)',marginTop:18}} type="button" onClick={()=>setRemove(true)}><Trash2 size={15}/>{t('حذف جلسه','Delete class')}</button>}</form><AlertDialog open={remove} onOpenChange={setRemove}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{t('این کلاس حذف شود؟','Delete this class?')}</AlertDialogTitle><AlertDialogDescription>{t('این کار قابل بازگشت نیست. برای حفظ سابقه، می‌توانید به‌جای حذف وضعیت را «لغوشده» قرار دهید.','This cannot be undone. To preserve the class record, you can change its status to cancelled instead.')}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>{t('انصراف','Cancel')}</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={e=>{e.preventDefault();onDelete()}}>{t('حذف جلسه','Delete class')}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>}
function AssessmentForm({student,busy,onSave,onCancel}:{student:Student,busy:boolean,onSave:(skills:Skills,note:string)=>Promise<void>,onCancel:()=>void}){const {t}=useL();const [skills,setSkills]=useState(student.skills);const [note,setNote]=useState('');return <form onSubmit={async e=>{e.preventDefault();await onSave(skills,note)}}>{skillKeys.map(k=>{const Icon=skillIcons[k];return <div className="skill-input" key={k}><label className="icon-with-text" htmlFor={'score-'+k}><Icon/>{t(skillNames[k][0],skillNames[k][1])}</label><input style={{width:95}} id={'score-'+k} type="number" dir="ltr" min={0} max={9} step={.5} required value={skills[k]} onChange={e=>setSkills({...skills,[k]:Number(e.target.value)})}/></div>})}<div className="text-area-wrap"><Field id="assessment-note" label={t('یادداشت و هدف جلسه بعد','Feedback and next learning goal')}><textarea id="assessment-note" value={note} maxLength={2000} onChange={e=>setNote(e.target.value)} placeholder={t('پیشرفت‌ها و موارد قابل تمرین…','Progress made and areas to practice…')}/></Field></div><FormActions busy={busy} onCancel={onCancel}/></form>}
